<title>Word Ladder Sprint</title>
<style>
  :root{--bg:#111827;--card:#172033;--text:#f8fafc;--muted:#9ca3af;--good:#22c55e;--bad:#ef4444;--warn:#f59e0b;--line:#263247}
  *{box-sizing:border-box}
  body{margin:0;font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:radial-gradient(circle at top,#25314d,#0b1020 70%);color:var(--text);min-height:100vh;display:grid;place-items:center;padding:18px}
  .app{width:min(760px,100%);background:rgba(23,32,51,.92);border:1px solid var(--line);border-radius:24px;padding:22px;box-shadow:0 24px 70px rgba(0,0,0,.35)}
