<body>
<div class="app">
  <h1>Word Ladder Sprint</h1>
  <p class="sub">Race from start to finish. Each move must be a real word and change exactly one letter.</p>

  <div class="top">
    <div class="word">
      <div class="label">Start</div>
      <div class="big" id="startWord">COLD</div>
    </div>
    <div class="arrow">→</div>
    <div class="word">
      <div class="label">Finish</div>
      <div class="big" id="endWord">WARM</div>
    </div>
  </div>

  <div class="bar">
    <button class="primary" id="newGame">New Sprint</button>
    <button class="ghost" id="undo">Undo</button>
    <button class="ghost" id="reset">Reset Run</button>
  </div>

  <div class="stats">
    <div class="stat"><span class="label">Time</span><b id="time">0.0s</b></div>
    <div class="stat"><span class="label">Moves</span><b id="moves">0</b></div>
    <div class="stat"><span class="label">Best</span><b id="best">—</b></div>
  </div>

  <form class="entry" id="form">
    <input id="guess" maxlength="4" autocomplete="off" placeholder="type next word" />
    <button class="primary">Play Word</button>
  </form>

  <div class="msg" id="msg"></div>

  <div class="path">
    <div class="label">Your ladder</div>
    <div class="chips" id="chips"></div>
  </div>

  <p class="small">
    Built-in puzzle set uses four-letter words. The game rejects wrong length, non-dictionary words, repeated words, and moves that change more or less than one letter.
  </p>
</div>

<script>
const WORDS = new Set(`
cold cord card ward warm
cold cord word worm warm
lead load goad gold
same came case cash
fire fare farm form
game gate date data
head heal teal tell
ship shop shot slot
dark dare care core
mile male mall ball
sand band bond bold
wind wine wise rise
`.trim().split(/\s+/));

const PUZZLES = [
  ["cold","warm"],
  ["lead","gold"],
  ["same","cash"],
  ["fire","form"],
  ["game","data"],
  ["head","tell"],
  ["ship","slot"],
  ["dark","core"],
  ["mile","ball"],
  ["sand","bold"],
  ["wind","rise"]
];

let start = "cold", end = "warm", path = ["cold"];
let running = false, finished = false, t0 = 0, elapsed = 0, timer = null;

const els = {
  startWord: document.getElementById("startWord"),
  endWord: document.getElementById("endWord"),
  time: document.getElementById("time"),
  moves: document.getElementById("moves"),
  best: document.getElementById("best"),
  guess: document.getElementById("guess"),
  msg: document.getElementById("msg"),
  chips: document.getElementById("chips"),
  form: document.getElementById("form"),
  newGame: document.getElementById("newGame"),
  undo: document.getElementById("undo"),
  reset: document.getElementById("reset")
};

function bestKey(){ return `wordLadderBest:${start}:${end}`; }

function fmt(ms){ return (ms / 1000).toFixed(1) + "s"; }

function diffCount(a,b){
  let d = 0;
  for(let i=0;i<a.length;i++) if(a[i] !== b[i]) d++;
  return d;
}

function setMsg(text, cls=""){
  els.msg.className = "msg " + cls;
  els.msg.textContent = text;
}

function startTimer(){
  if(running) return;
  running = true;
  t0 = performance.now() - elapsed;
  timer = setInterval(() => {
    elapsed = performance.now() - t0;
    els.time.textContent = fmt(elapsed);
  }, 50);
}

function stopTimer(){
  running = false;
  clearInterval(timer);
}

function render(){
  els.startWord.textContent = start.toUpperCase();
  els.endWord.textContent = end.toUpperCase();
  els.moves.textContent = Math.max(0, path.length - 1);
  els.time.textContent = fmt(elapsed);
  els.chips.innerHTML = "";
  path.forEach(w => {
    const chip = document.createElement("div");
    chip.className = "chip" + (w === end ? " done" : "");
    chip.textContent = w.toUpperCase();
    els.chips.appendChild(chip);
  });

  const best = localStorage.getItem(bestKey());
  els.best.textContent = best ? fmt(Number(best)) : "—";
  els.guess.placeholder = `next from ${path[path.length - 1].toUpperCase()}`;
  els.guess.value = "";
  els.guess.focus();
}

function resetRun(){
  stopTimer();
  elapsed = 0;
  finished = false;
  path = [start];
  setMsg("Timer starts when you play the first valid move.", "warn");
  render();
}

function newGame(){
  const pick = PUZZLES[Math.floor(Math.random() * PUZZLES.length)];
  start = pick[0];
  end = pick[1];
  resetRun();
}

function play(word){
  word = word.toLowerCase().trim();

  if(finished) return setMsg("Run finished. Start a new sprint or reset.", "warn");
  if(word.length !== start.length) return setMsg(`Use a ${start.length}-letter word.`, "bad");
  if(!/^[a-z]+$/.test(word)) return setMsg("Letters only.", "bad");
  if(!WORDS.has(word)) return setMsg("Not in this game's dictionary.", "bad");
  if(path.includes(word)) return setMsg("You already used that word.", "bad");

  const current = path[path.length - 1];
  const diff = diffCount(current, word);
  if(diff !== 1) return setMsg(`Invalid move. ${current.toUpperCase()} → ${word.toUpperCase()} changes ${diff} letters.`, "bad");

  startTimer();
  path.push(word);

  if(word === end){
    elapsed = performance.now() - t0;
    stopTimer();
    finished = true;

    const oldBest = localStorage.getItem(bestKey());
    const beat = !oldBest || elapsed < Number(oldBest);
    if(beat) localStorage.setItem(bestKey(), String(elapsed));

    setMsg(`Finished in ${fmt(elapsed)} with ${path.length - 1} moves${beat ? " — new best." : "."}`, "good");
  } else {
    setMsg("Valid move.", "good");
  }

  render();
}

els.form.addEventListener("submit", e => {
  e.preventDefault();
  play(els.guess.value);
});

els.undo.addEventListener("click", () => {
  if(path.length <= 1 || finished) return;
  path.pop();
  setMsg("Last move undone.", "warn");
  render();
});

els.reset.addEventListener("click", resetRun);
els.newGame.addEventListener("click", newGame);

resetRun();
</script>
</body>
</html>

