<body>
<div class="app">
  <h1>Word Ladder Sprint</h1>
  <p class="sub">Race from start to finish. Each move must be a real word and change exactly one letter.</p>

  <div class="top">
    <div class="word"><div class="label">Start</div><div class="big" id="startWord"></div></div>
    <div class="arrow">→</div>
    <div class="word"><div class="label">Finish</div><div class="big" id="endWord"></div></div>
  </div>

  <div class="bar">
    <button class="primary" id="newGame">New Sprint</button>
    <button class="hint" id="hintBtn">Hint</button>
    <button class="ghost" id="undo">Undo</button>
    <button class="ghost" id="reset">Reset Run</button>
  </div>

  <div class="stats">
    <div class="stat"><span class="label">Time</span><b id="time">0.0s</b></div>
    <div class="stat"><span class="label">Moves</span><b id="moves">0</b></div>
    <div class="stat"><span class="label">Hints</span><b id="hints">0</b></div>
    <div class="stat"><span class="label">Best</span><b id="best">—</b></div>
    <div class="stat"><span class="label">Streak</span><b id="streak">0</b></div>
    <div class="stat"><span class="label">Best Streak</span><b id="bestStreak">0</b></div>
  </div>

  <div class="inputPanel" id="inputPanel">
    <div class="label">Next word</div>
    <input id="hiddenInput" class="hiddenInput" autocomplete="off" autocapitalize="characters" spellcheck="false" inputmode="text" />
    <div class="slots" id="slots"></div>
    <div class="inputActions">
      <button class="ghost" id="backBtn">Backspace</button>
      <button class="primary" id="playBtn">Play Word</button>
    </div>
    <div class="keypad" id="keypad"></div>
  </div>

  <div class="msg" id="msg"></div>

  <div class="summary" id="summary">
    <div class="label">Finish summary</div>
    <div class="summaryGrid">
      <div class="summaryItem"><span class="label">Time</span><b id="sumTime">—</b></div>
      <div class="summaryItem"><span class="label">Moves</span><b id="sumMoves">—</b></div>
      <div class="summaryItem"><span class="label">Hints</span><b id="sumHints">—</b></div>
      <div class="summaryItem"><span class="label">Streak</span><b id="sumStreak">—</b></div>
    </div>
  </div>

  <div class="path">
    <div class="label">Your ladder</div>
    <div class="chips" id="chips"></div>
  </div>

  <p class="small">Mobile keyboard uses thumb-sized rows with six letter columns max. Desktop typing still works normally, and Enter plays the word.</p>
</div>

<script>
const PUZZLE_PATHS = [
  ["cold","cord","card","ward","warm"],["cold","cord","word","worm","warm"],["lead","load","goad","gold"],
  ["same","came","case","cash"],["fire","fare","farm","form"],["game","gate","date","data"],
  ["head","heal","teal","tell"],["ship","shop","shot","slot"],["dark","dare","care","core"],
  ["mile","male","mall","ball"],["sand","band","bond","bold"],["wind","wine","wise","rise"],
  ["love","live","line","pine","pink"],["maze","made","mate","math"],["toon","soon","soot","slot"],
  ["hard","hare","care","cure"],["pale","pole","poll","pool"],["seed","send","sand","band"],
  ["rock","rack","race","lace"],["moon","mood","wood","word"],["bike","bile","mile","mild"],
  ["fish","fist","fast","cast"],["door","poor","pour","sour"],["lamp","limp","lime","like"],
  ["bake","bike","like","line"]
];

const EXTRA_WORDS = `
cold cord card ward warm word worm lead load goad gold same came case cash fire fare farm form game gate date data
head heal teal tell ship shop shot slot dark dare hare care core cure mile male mall ball mild sand band bond bold send seed
wind wine wise rise love live line pine pink maze made mate math toon soon soot pale pole poll pool rock rack race lace
moon mood wood bike bile like fish fist fast cast door poor pour sour lamp limp lime bake sold told toll tall tail bald bard bare
`.trim().split(/\s+/);

const WORDS = new Set([...PUZZLE_PATHS.flat(), ...EXTRA_WORDS]);

let start = "cold", end = "warm", path = ["cold"];
let running = false, finished = false, t0 = 0, elapsed = 0, timer = null, hintCount = 0;
let typed = "";

const els = {
  startWord: document.getElementById("startWord"), endWord: document.getElementById("endWord"),
  time: document.getElementById("time"), moves: document.getElementById("moves"), hints: document.getElementById("hints"),
  best: document.getElementById("best"), streak: document.getElementById("streak"), bestStreak: document.getElementById("bestStreak"),
  msg: document.getElementById("msg"), chips: document.getElementById("chips"), newGame: document.getElementById("newGame"),
  hintBtn: document.getElementById("hintBtn"), undo: document.getElementById("undo"), reset: document.getElementById("reset"),
  summary: document.getElementById("summary"), sumTime: document.getElementById("sumTime"), sumMoves: document.getElementById("sumMoves"),
  sumHints: document.getElementById("sumHints"), sumStreak: document.getElementById("sumStreak"), slots: document.getElementById("slots"),
  hiddenInput: document.getElementById("hiddenInput"), inputPanel: document.getElementById("inputPanel"),
  backBtn: document.getElementById("backBtn"), playBtn: document.getElementById("playBtn"), keypad: document.getElementById("keypad")
};

function bestKey(){ return `wordLadderBest:${start}:${end}`; }
function fmt(ms){ return (ms / 1000).toFixed(1) + "s"; }
function getStreak(){ return Number(localStorage.getItem("wordLadderStreak") || 0); }
function getBestStreak(){ return Number(localStorage.getItem("wordLadderBestStreak") || 0); }
function setStreak(v){ localStorage.setItem("wordLadderStreak", String(v)); }
function setBestStreak(v){ localStorage.setItem("wordLadderBestStreak", String(v)); }

function diffCount(a,b){
  let d = 0;
  for(let i=0;i<a.length;i++) if(a[i] !== b[i]) d++;
  return d;
}

function neighbors(word){
  return [...WORDS].filter(w => w.length === word.length && diffCount(word, w) === 1);
}

function shortestPath(from, to){
  const queue = [[from]];
  const seen = new Set([from]);
  while(queue.length){
    const route = queue.shift();
    const current = route[route.length - 1];
    if(current === to) return route;
    for(const next of neighbors(current)){
      if(seen.has(next)) continue;
      seen.add(next);
      queue.push([...route, next]);
    }
  }
  return null;
}

function setMsg(text, cls=""){
  els.msg.className = "msg " + cls;
  els.msg.textContent = text;
}

function startTimer(){
  if(running) return;
  running = true;
  t0 = performance.now() - elapsed;
  timer = setInterval(() => {
    elapsed = performance.now() - t0;
    els.time.textContent = fmt(elapsed);
  }, 50);
}

function stopTimer(){
  running = false;
  clearInterval(timer);
}

function focusInput(){
  els.hiddenInput.focus({preventScroll:true});
}

function drawSlots(){
  els.slots.innerHTML = "";
  for(let i = 0; i < start.length; i++){
    const slot = document.createElement("div");
    slot.className = "slot" + (i === Math.min(typed.length, start.length - 1) && !finished ? " active" : "");
    slot.textContent = typed[i] ? typed[i].toUpperCase() : "";
    els.slots.appendChild(slot);
  }
}

function setTyped(value){
  typed = value.toLowerCase().replace(/[^a-z]/g, "").slice(0, start.length);
  els.hiddenInput.value = typed.toUpperCase();
  drawSlots();
}

function addLetter(letter){
  if(finished || typed.length >= start.length) return;
  setTyped(typed + letter);
}

function backspace(){
  if(finished) return;
  setTyped(typed.slice(0, -1));
  focusInput();
}

function clearTyped(){
  setTyped("");
}

function makeKey(label, className, action){
  const btn = document.createElement("button");
  btn.className = className;
  btn.type = "button";
  btn.textContent = label;
  btn.addEventListener("click", action);
  return btn;
}

function buildKeypad(){
  els.keypad.innerHTML = "";

  const rows = ["ABCDEF", "GHIJKL", "MNOPQR", "STUVWX", "YZ"];

  rows.forEach(keys => {
    const wrap = document.createElement("div");
    wrap.className = "keyRow";

    keys.split("").forEach(k => {
      wrap.appendChild(makeKey(k, "key", () => {
        addLetter(k.toLowerCase());
        focusInput();
      }));
    });

    els.keypad.appendChild(wrap);
  });

  const controls = document.createElement("div");
  controls.className = "keyRow controls";
  controls.appendChild(makeKey("Backspace", "key utility", backspace));
  controls.appendChild(makeKey("Play", "key utility primary", () => play(typed)));
  els.keypad.appendChild(controls);
}

function updateStreakDisplay(){
  els.streak.textContent = getStreak();
  els.bestStreak.textContent = getBestStreak();
}

function render(){
  els.startWord.textContent = start.toUpperCase();
  els.endWord.textContent = end.toUpperCase();
  els.moves.textContent = Math.max(0, path.length - 1);
  els.hints.textContent = hintCount;
  els.time.textContent = fmt(elapsed);
  updateStreakDisplay();

  els.chips.innerHTML = "";
  path.forEach(w => {
    const chip = document.createElement("div");
    chip.className = "chip" + (w === end ? " done" : "");
    chip.textContent = w.toUpperCase();
    els.chips.appendChild(chip);
  });

  const best = localStorage.getItem(bestKey());
  els.best.textContent = best ? fmt(Number(best)) : "—";
  drawSlots();
}

function resetRun(){
  stopTimer();
  elapsed = 0;
  finished = false;
  hintCount = 0;
  path = [start];
  clearTyped();
  els.summary.classList.remove("show");
  setMsg("Timer starts when you play the first valid move.", "warn");
  render();
  focusInput();
}

function newGame(){
  const pick = PUZZLE_PATHS[Math.floor(Math.random() * PUZZLE_PATHS.length)];
  start = pick[0];
  end = pick[pick.length - 1];
  resetRun();
}

function useHint(){
  if(finished) return setMsg("Run finished. Start a new sprint or reset.", "warn");
  const current = path[path.length - 1];
  const route = shortestPath(current, end);
  if(!route || route.length < 2) return setMsg("No fair path from here. Undo or reset.", "bad");
  hintCount++;
  const next = route[1];
  setTyped(next);
  setMsg(`Hint filled in ${next.toUpperCase()}.`, "warn");
  render();
  setTyped(next);
  focusInput();
}

function finishRun(){
  elapsed = performance.now() - t0;
  stopTimer();
  finished = true;

  const oldBest = localStorage.getItem(bestKey());
  const beat = !oldBest || elapsed < Number(oldBest);
  if(beat) localStorage.setItem(bestKey(), String(elapsed));

  let streakText;
  if(hintCount === 0){
    const nextStreak = getStreak() + 1;
    setStreak(nextStreak);
    if(nextStreak > getBestStreak()) setBestStreak(nextStreak);
    streakText = `Survived, now ${nextStreak}`;
  } else {
    setStreak(0);
    streakText = "Broken by hint";
  }

  els.sumTime.textContent = fmt(elapsed);
  els.sumMoves.textContent = path.length - 1;
  els.sumHints.textContent = hintCount;
  els.sumStreak.textContent = streakText;
  els.summary.classList.add("show");

  setMsg(`Finished. ${hintCount === 0 ? "No-hint streak survived." : "Hint used, streak reset."}${beat ? " New best time." : ""}`, hintCount === 0 ? "good" : "warn");
}

function play(word){
  word = word.toLowerCase().trim();

  if(finished) return setMsg("Run finished. Start a new sprint or reset.", "warn");
  if(word.length !== start.length) return setMsg(`Fill all ${start.length} letters.`, "bad");
  if(!/^[a-z]+$/.test(word)) return setMsg("Letters only.", "bad");
  if(!WORDS.has(word)) return setMsg("Not in this game's dictionary.", "bad");
  if(path.includes(word)) return setMsg("You already used that word.", "bad");

  const current = path[path.length - 1];
  const diff = diffCount(current, word);
  if(diff !== 1) return setMsg(`Invalid move. ${current.toUpperCase()} → ${word.toUpperCase()} changes ${diff} letters.`, "bad");

  const stillSolvable = shortestPath(word, end);
  if(!stillSolvable) return setMsg("That word is valid, but it strands this sprint. Try another move.", "bad");

  startTimer();
  path.push(word);

  if(word === end) finishRun();
  else setMsg("Valid move.", "good");

  clearTyped();
  render();
  focusInput();
}

els.hiddenInput.addEventListener("input", e => setTyped(e.target.value));

els.hiddenInput.addEventListener("keydown", e => {
  if(e.key === "Enter"){
    e.preventDefault();
    play(typed);
  }
  if(e.key === "Backspace"){
    e.preventDefault();
    backspace();
  }
});

els.inputPanel.addEventListener("click", focusInput);
els.backBtn.addEventListener("click", backspace);
els.playBtn.addEventListener("click", () => play(typed));
els.hintBtn.addEventListener("click", useHint);

els.undo.addEventListener("click", () => {
  if(path.length <= 1 || finished) return;
  path.pop();
  setMsg("Last move undone.", "warn");
  render();
  focusInput();
});

els.reset.addEventListener("click", resetRun);
els.newGame.addEventListener("click", newGame);

buildKeypad();
newGame();
</script>
</body>
</html>
